CREATE SCHEMA IF NOT EXISTS catalog;
CREATE TABLE IF NOT EXISTS catalog.categories(id uuid PRIMARY KEY,name text UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS catalog.products(id uuid PRIMARY KEY,sku text UNIQUE NOT NULL,name text NOT NULL,description text NULL,price numeric(12,2) NOT NULL CHECK(price>=0),stock_quantity integer NOT NULL CHECK(stock_quantity>=0),category_id uuid NOT NULL REFERENCES catalog.categories(id),active boolean NOT NULL DEFAULT true,created_by uuid NOT NULL,updated_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS catalog.audit_log(id bigserial PRIMARY KEY,product_id uuid NOT NULL,action text NOT NULL,actor_id uuid NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS catalog.stock_movements(id bigserial PRIMARY KEY,product_id uuid NOT NULL,quantity_delta integer NOT NULL,reason text NOT NULL,actor_id uuid NULL,correlation_id uuid NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS catalog.outbox(event_id uuid PRIMARY KEY,event_type text NOT NULL,payload jsonb NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz NULL);
CREATE TABLE IF NOT EXISTS catalog.stock_reservations(id uuid PRIMARY KEY,order_id uuid UNIQUE NOT NULL,state text NOT NULL,correlation_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS catalog.stock_reservation_items(reservation_id uuid NOT NULL REFERENCES catalog.stock_reservations(id),product_id uuid NOT NULL REFERENCES catalog.products(id),quantity integer NOT NULL CHECK(quantity>0),PRIMARY KEY(reservation_id,product_id));
